    private void btnHitungActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnHitungActionPerformed
        // TODO add your handling code here:
        float nAbsen, nTugas, nUts, nUas, nAngka, nBobot;
        String nHuruf, ket;
        
        nAbsen = Float.parseFloat(txtAbsen.getText());
        nTugas = Float.parseFloat(txtTugas.getText());
        nUts = Float.parseFloat(txtUts.getText());
        nUas = Float.parseFloat(txtUas.getText());
        
        nAngka = (float) ((0.1 * nAbsen) + (0.1 * nTugas) + (0.3 * nUts) + (0.5 * nUas));
        
        if(nAngka > 84) {
            nHuruf = "a";
            nBobot = 4;
            ket = "sangat memuaskan";
        } else if (nAngka > 70) {
            nHuruf = "b";
            nBobot = 3;
            ket = "memuaskan";
        } else if (nAngka > 54) {
            nHuruf = "c";
            nBobot = 1;
            ket = "cukup memuaskan";
        } else if (nAngka > 39){
            nHuruf = "d";
            nBobot = 1;
            ket = "kurang memuaskan";
        } else {
            nHuruf = "e";
            nBobot = 0;
            ket = "gagal";
        }
        
        txtNAngka.setText(String.valueOf(nAngka));
        txtNHuruf.setText(String.valueOf(nHuruf));
        txtBobot.setText(String.valueOf(nBobot));
        txtKet.setText(ket);
        
    }//GEN-LAST:event_btnHitungActionPerformed

